local ADDON, ns = ...
local L = ns.L

L.RANK_RULES_LINK = "Ranking rules"
L.RANK_RULES_BACK = "< Back"
L.RANK_RULES_NOTE = "How this ranking is calculated from the records held on this computer. Missing evidence stays unknown."
L.RANK_RULES_LINK_TIP = "Open the scoring, ordering, evidence and visibility rules in this window."
L.RANK_RULES_SCORE = "Scoring"
L.RANK_RULES_ORDER = "Order and ties"
L.RANK_RULES_EVIDENCE = "Evidence"
L.RANK_RULES_VISIBILITY = "Who can see it"
L.RANK_RULES_LIMITS = "Counting limits"

L.RANK_RULE_DONORS_TITLE = "Donor ranking"
L.RANK_RULE_DONORS_SCORE = "Qualifying incoming gifts are added in copper. Returned, outgoing, transferred and excluded ledger lines do not add to the total."
L.RANK_RULE_DONORS_DUES = "When the Treasurer's book is shared outside its private view, the possible weekly dues portion is removed. Other keeper books show qualifying gifts as recorded."
L.RANK_RULE_DONORS_ORDER = "Higher qualifying copper comes first; equal totals are ordered by name."
L.RANK_RULE_DONORS_EVIDENCE = "This client ranks the books it currently holds. A missing or older book is missing or older evidence, not zero."
L.RANK_RULE_DONORS_VISIBILITY = "The King, his Stewards and the keepers can see it. Other members see it only while the King's ranking switch is open."

L.RANK_RULE_GUILD_TREASURY_TITLE = "Guild treasury ranking"
L.RANK_RULE_GUILD_TREASURY_SCORE = "Each guild's total is the gold in its authorized bank snapshot plus each item's known configured or vendor value. Unpriced items are not invented into the value."
L.RANK_RULE_GUILD_TREASURY_ORDER = "Higher total comes first; ties use higher known average level, then guild name. The Federal Treasury is shown separately and does not take a place."
L.RANK_RULE_GUILD_TREASURY_EVIDENCE = "Each row uses the latest authorized snapshot held here. Pending item prices make its total an 'at least' amount. Missing guilds and unpriced items remain unknown."
L.RANK_RULE_GUILD_TREASURY_VISIBILITY = "Only the existing private guild-treasury audience can see this ranking. It is not published to the army."

L.RANK_RULE_CHURCH_TITLE = "Church service ranking"
L.RANK_RULE_CHURCH_SCORE = "A confirmed recruit gives %d points. A recruit still in Olympus after %d days gives %d more. A leader also receives %d%%, %d%% and %d%% of the own points earned at the first three levels below them; shares do not compound."
L.RANK_RULE_CHURCH_ORDER = "Higher total score comes first; ties use higher own points, then name. Week, 30-day and all-time windows count only evidence dated in that window."
L.RANK_RULE_CHURCH_EVIDENCE = "Only confirmed recruit and later-stay records held by the Church books count. Missing records are unknown and do not create points."
L.RANK_RULE_CHURCH_VISIBILITY = "The Church audience sees the full ranking. The public page shows only opted-in rows while the authorized publication switch is open."

L.RANK_RULE_CHURCH_FULLNESS_TITLE = "Guild fullness ranking"
L.RANK_RULE_CHURCH_FULLNESS_ORDER = "More completed qualifying days come first. Ties use the higher average of the qualifying daily averages, then guild name."
L.RANK_RULE_CHURCH_FULLNESS_VISIBILITY = "This is private to the Church audience; it is not part of the public Church ranking."

L.RANK_RULE_ARENA_TITLE = "Arena rating"
L.RANK_RULE_ARENA_SCORE = "A fighter with no carried rating starts at %d. Between seasons, a retained rating moves halfway back toward %d. K=%d applies only while the fighter is unsettled and has fewer than %d rated fights; a settled fighter can therefore start outside %d and uses K=%d, or K=%d from rating %d. Each level of difference counts as %d rating points; the total expected-score gap is capped at %d."
L.RANK_RULE_ARENA_REPEAT = "Repeated fights between the same pair within %d hours progressively count at 1, 1/2, 1/4 and so on."
L.RANK_RULE_ARENA_LIMITS = "A rated fight needs at least %d seconds per round on average. At most %d fights per player per server day and %d fights against the same opponent in %d days count. Rehearsals and unconfirmed fights do not count."
L.RANK_RULE_ARENA_ORDER = "All-time ranks use higher rating, then more rated fights, then name; equal ratings share a place. Period views use rating gained, wins, fewer losses, current rating, then name."
L.RANK_RULE_ARENA_EVIDENCE = "The ranking is rebuilt from retained rated fight records. A missing or rejected record does not create a result."
L.RANK_RULE_ARENA_VISIBILITY = "Games staff always see it. Members see it only while an authorized publisher's Arena switch is open."

L.RANK_RULE_BONES_TITLE = "Bones ranking"
L.RANK_RULE_BONES_SCORE = "The current calendar month ranks confirmed player-versus-player wins. Practice, house games, same-owner alts, hidden players and records whose two signed halves do not agree do not count."
L.RANK_RULE_BONES_LIMITS = "A game needs at least %d seconds. At most %d games per player per server day and %d games against the same opponent in %d days count."
L.RANK_RULE_BONES_ORDER = "More wins comes first; ties use fewer games, then the earlier time that win total was reached, then name. The closed previous month's champion and podium are retained separately."
L.RANK_RULE_BONES_EVIDENCE = "Only matching signed game halves retained by this client count. Missing halves stay unknown."
L.RANK_RULE_BONES_VISIBILITY = "Games staff always see it. Members see it only while an authorized publisher's Bones switch is open."

L.RANK_RULE_LEVEL_TITLE = "Top levels"
L.RANK_RULE_LEVEL_SCORE = "There are no points: characters are ordered by their latest reported level."
L.RANK_RULE_LEVEL_ORDER = "Higher level comes first; equal levels are ordered by character name. The page shows at most %d characters, %d at a time."
L.RANK_RULE_LEVEL_EVIDENCE = "Only the top-character lists in fresh guild reports held by this client are included. This is a local census view, not server certification."
L.RANK_RULE_LEVEL_VISIBILITY = "Every Olympus member can see the same ranking page built from the reports their client has heard."

L.RANK_RULE_DEBTORS_TITLE = "Crafting fee collection order"
L.RANK_RULE_DEBTORS_SCORE = "This is not an honour ranking. A confirmed guild fee is due %d hours after the completed direct sale. Open fees are grouped by crafter, with total owed and already-overdue amounts kept separately."
L.RANK_RULE_DEBTORS_ORDER = "More overdue copper comes first, then more total copper owed, then name. The collection tier changes at the due time, after %d hours, and after %d hours."
L.RANK_RULE_DEBTORS_EVIDENCE = "Only confirmed fee-ledger entries held by the fee desk or its latest private answer count. Unconfirmed entries wait outside the ranking."
L.RANK_RULE_DEBTORS_VISIBILITY = "Only the existing private fee-ledger readers can see it. Nothing here publishes debt or moves gold automatically."

L.RANK_RULE_WANTED_TITLE = "Wanted and Slayer rankings"
L.RANK_RULE_WANTED_BOUNTY = "For current scored evidence, a counted death adds the victim's level and highest verified office bonus to the Horde player's open bounty: King 100, High Council 50, Guild Master 30, Legate 20, another office 10, member 0, up to an open-bounty cap of %d. A current scored repeat inside %d minutes adds neither bounty nor another counted kill. Older compatibility evidence without scoring fields keeps its legacy behavior: it adds one historical kill and up to 1 bounty point below the same cap; the current scored-repeat protection is not applied."
L.RANK_RULE_WANTED_SLAYER = "A current scored qualifying Horde kill gives one base point per %d Horde levels, rounded up, plus the entire open bounty and %d points for an eligible revenge. Revenge must answer that player's own death within %d days. An older compatibility claim without scoring fields pays only the open bounty, with no level base or revenge."
L.RANK_RULE_WANTED_LIMITS = "For current scored evidence, the level base counts at most once for the same killer and target in %d minutes, and revenge at most once in %d hours. Deaths and kills in instances do not count. Zero-bounty, zero-kill Horde entries stay off the visible Wanted list."
L.RANK_RULE_WANTED_ORDER = "Wanted is ordered by higher current open bounty, then more counted lifetime kills, then name. Monthly and all-time Slayers are ordered by more points, then the earlier time that total was reached, then stable identity. Only a signed global top three controls the Slayer frames."
L.RANK_RULE_WANTED_EVIDENCE = "The local boards use this client's own retained rows and the verified rows Olympus members shared with it; they are not server-certified totals. Missing evidence stays unknown. Old scores are recalculated only where retained facts prove the result; otherwise the old total stays archived instead of being guessed into the ranking."
L.RANK_RULE_WANTED_VISIBILITY = "Olympus members can read these rules and the records their own client holds. Only the King, signed High Council and the author can publish the signed global top three. Location rows and map markers also obey the separate location-sharing and moderation gates."

