	L.RANK_RULE_CHURCH_FULLNESS_VISIBILITY = "Este ranking e privado para o publico da Igreja; ele nao faz parte do ranking publico da Igreja."

	L.RANK_RULE_ARENA_TITLE = "Rating da Arena"
