	L.RANK_RULE_DEBTORS_ORDER = "Mais cobre atrasado vem primeiro, depois mais cobre total devido e depois o nome. O nivel de cobranca muda no vencimento, apos %d horas e apos %d horas."
	L.RANK_RULE_DEBTORS_EVIDENCE = "Somente entradas confirmadas do livro de taxas guardadas pela mesa ou por sua ultima resposta privada contam. Entradas nao confirmadas esperam fora do ranking."
	L.RANK_RULE_DEBTORS_VISIBILITY = "Somente os leitores privados atuais do livro de taxas podem ver. Nada aqui publica divida ou move ouro automaticamente."

